def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v = v.split('+')[0]

        # Split on '-' to separate base version and pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
            prerelease_identifiers = prerelease.split('.')
        else:
            base = v
            prerelease_identifiers = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both are None (no pre-release), they're equal
        if pre1 is None and pre2 is None:
            return 0
        # If one has pre-release and other doesn't, pre-release sorts first
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both are numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_num1:
                # id1 is numeric, id2 is not; numeric sorts first
                return -1
            elif is_num2:
                # id2 is numeric, id1 is not; numeric sorts first
                return 1
            else:
                # Both are non-numeric, compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(item):
        idx, v = item
        major, minor, patch, prerelease = parse_version(v)
        # Return tuple that can be compared: (major, minor, patch, prerelease_sort_key, original_index)
        # For prerelease, we need a key that sorts None after non-None
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after pre-releases
        else:
            # Convert each identifier to a comparable form
            prerelease_key = (0,) + tuple(
                (0, int(id)) if id.isdigit() else (1, id)
                for id in prerelease
            )
        return (major, minor, patch, prerelease_key, idx)

    # Enumerate to maintain input order for equal versions
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

